result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/save.ts", "content": "import { z } from "zod";

/** Version 1: minimal save format. */
export const SaveV1 = z.object({
  v: z.literal(1),
  gold: z.number(),
  pos: z.tuple([z.number(), z.number()]),
});
export type SaveV1 = z.infer<typeof SaveV1>;

/** Version 2: adds an inventory list. */
export const SaveV2 = SaveV1.extend({
  v: z.literal(2),
  inventory: z.array(z.string()),
});
export type SaveV2 = z.infer<typeof SaveV2>;

/** Version 3: pos becomes an object, settings gains a defaulted volume. */
export const SaveV3 = z.object({
  v: z.literal(3),
  gold: z.number(),
  pos: z.object({ x: z.number(), y: z.number() }),
  inventory: z.array(z.string()),
  settings: z.object({ volume: z.number().min(0).max(1).default(0.8) }),
});
export type SaveV3 = z.infer<typeof SaveV3>;

// Stepwise migrations: each takes a validated object of version N
// and returns a structurally valid object of version N+1.

export function migrateV1toV2(save: SaveV1): SaveV2 {
  return { ...save, v: 2, inventory: [] };
}

export function migrateV2toV3(save: SaveV2): SaveV3 {
  const [x, y] = save.pos;
  return {
    v: 3,
    gold: save.gold,
    pos: { x, y },
    inventory: save.inventory,
    // volume default applied by SaveV3.parse; set explicitly for clarity
    settings: { volume: 0.8 },
  };
}

/**
 * Parse arbitrary data as any known save version and migrate it,
 * step by step, to the latest (v3) format.
 * Throws ZodError if the input matches no version's schema.
 */
export function migrateToLatest(data: unknown): SaveV3 {
  const v = (data as { v?: unknown } | null)?.v;

  switch (v) {
    case 1:
      return migrateV2toV3(migrateV1toV2(SaveV1.parse(data)));
    case 2:
      return migrateV2toV3(SaveV2.parse(data));
    case 3:
      return SaveV3.parse(data);
    default:
      throw new z.ZodError([
        {
          code: "custom",
          path: ["v"],
          message: "unknown or missing save version",
        },
      ]);
  }
}
