result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/save.test.ts", "content": "import { describe, expect, it } from "vitest";
import { z } from "zod";
import { SaveV1, SaveV2, SaveV3, migrateToLatest, type SaveV3 } from "./save";

const fixtureV1 = { v: 1 as const, gold: 120, pos: [10, -4] };
const fixtureV2 = {
  v: 2 as const,
  gold: 250,
  pos: [7, 3],
  inventory: ["sword", "potion"],
};
const fixtureV3 = {
  v: 3 as const,
  gold: 999,
  pos: { x: 1.5, y: -2.5 },
  inventory: ["key"],
  settings: { volume: 0.5 },
};

/** Deterministic PRNG (mulberry32) so the fuzz run is reproducible. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Produce 200 seeded structurally-broken variants of valid saves. */
function* brokenVariants(seed: number): Generator<unknown> {
  const bases = [fixtureV1, fixtureV2, fixtureV3];
  const wrongValues = [
    "not-a-number",
    null,
    undefined,
    {},
    [],
    true,
    Number.NaN, // NaN fails z.number() in non-optional strictness? NaN passes... see filter below
    "42",
    [1],
  ];
  const rand = mulberry32(seed);
  for (let i = 0; i < 200; i++) {
    const base = structuredClone(bases[i % bases.length]) as Record<
      string,
      unknown
    >;
    const keys = Object.keys(base);
    if (rand() < 0.5 && keys.length > 1) {
      // delete a random key (never `v`, so version dispatch still happens
      // and validation — not the dispatcher — must reject it)
      const deletable = keys.filter((k) => k !== "v");
      delete base[deletable[Math.floor(rand() * deletable.length)]];
    } else {
      // corrupt a random key's value with a wrong type
      const k = keys[Math.floor(rand() * keys.length)];
      let bad = wrongValues[Math.floor(rand() * wrongValues.length)];
      if (bad === undefined) {
        // undefined assignment is invisible on plain objects; use another poison
        bad = Symbol("nope");
      }
      base[k] = bad;
    }
    yield base;
  }
}

describe("migrateToLatest", () => {
  it("migrates every valid version fixture to something SaveV3 accepts", () => {
    for (const fixture of [fixtureV1, fixtureV2, fixtureV3]) {
      const migrated = migrateToLatest(structuredClone(fixture));
      expect(() => SaveV3.parse(migrated)).not.toThrow();
      expect(migrated.v).toBe(3);
    }
  });

  it("applies v3 defaults when settings is absent (v1/v2 paths)", () => {
    const fromV1 = migrateToLatest(fixtureV1);
    expect(fromV1.settings.volume).toBe(0.8);
  });

  it("migrates a v1 fixture to an exact expected v3 object", () => {
    const expected: SaveV3 = {
      v: 3,
      gold: 120,
      pos: { x: 10, y: -4 },
      inventory: [],
      settings: { volume: 0.8 },
    };
    expect(migrateToLatest(fixtureV1)).toEqual(expected);
  });

  it("preserves explicit volume from v3 input", () => {
    expect(migrateToLatest(fixtureV3).settings.volume).toBe(0.5);
  });

  it("rejects unknown-version and non-object inputs", () => {
    for (const junk of [
      null,
      undefined,
      42,
      "save",
      [],
      { gold: 1 },
      { v: 99 },
    ]) {
      expect(() => migrateToLatest(junk)).toThrow(z.ZodError);
    }
  });

  it.fuzz("fuzz", () => {});
});
"})
